G={'v':v,'v2':v**2,'sqrtv':np.sqrt(v),'sinv':np.sin(v),'cosv':np.cos(v),'expv':np.exp(-v)}
H={'t':t,'sqrtt':np.sqrt(t),'sint':np.sin(t),'cost':np.cos(t),'expt':np.exp(-t)}
lib={}
for d in (F,G,H): lib.update(d)
for n,f in F.items():
  for m,g in G.items(): lib[f'{n}*{m}']=f*g
  for m,h in H.items(): lib[f'{n}*{m}']=f*h
for n,g in G.items():
  for m,h in H.items(): lib[f'{n}*{m}']=g*h
